noresult={'N088','N167','N234','U046'}
output=[]
for r in records:
 ident=r['id'];query='"'+r['title']+'"'
 if ident=='N369':query='"'+r['doi']+'"'
 if ident=='N479':query='"'+r['doi']+'"'
 if ident=='U054':query='"'+r['doi']+'"'
 if ident in review:
  decision,criterion,url,level,evidence,note=review[ident];match='Exact title/DOI matched in the cited primary publisher, author or institutional source.'
  if ident=='U408':match='Exact title/DOI matched in secondary indexed result only; primary title not independently verified.'
  if ident=='U411':match='Exact title/DOI matched in secondary bibliographic metadata only.'
 elif ident in metadata:
  url,note=metadata[ident];decision='Include';criterion='Full-text assessment needed';level='Metadata only';match='Exact title and/or DOI matched in metadata; primary substantive text not retrieved.'
  evidence='Only bibliographic identification and the supplied incomplete abstract were available for this review. '+note
 elif ident in noresult:
  url='https://doi.org/'+r['doi'];decision='Include';criterion='Full-text assessment needed';level='Search unsuccessful';match='No matching accessible primary article located in the exact-title/DOI searches.'
  note='Exact-title search (and DOI retries where noted) did not return accessible matching primary content. Known IEEE/DOI route was attempted and failed; no article read.'
  evidence='The supplied excerpt/title does not establish all eligibility conditions. Access failure is not an exclusion reason; advance to full-text assessment.'
 elif ident=='U054':
  url='https://www.mdpi.com/2075-4418/16/13/1996';decision='Include';criterion='Full-text assessment needed';level='Metadata only';match='Exact title and DOI matched in publisher-indexed and PubMed records.'
  evidence='Publisher-indexed method excerpts describe quantum classifier/noise experiments; supplied complete abstract also mentions feature stability and SHAP. Cannot determine whether attribution stability is separately assessed from feature selection/performance.'
  note='MDPI direct open returned429; PMC recaptcha. Some primary method excerpts retrieved in search, but no complete accessible primary article/abstract was independently opened. Conservative advance.'
 else:raise ValueError(ident)
 output.append({'id':ident,'decision':decision,'criterion':criterion,'rationale':evidence,'search_query':query,'source_url':url,'title_match':match,'evidence_level':level,'evidence_text':evidence,'access_note':note})
assert len(output)==37 and len({r['id'] for r in output})==37
assert {r['id'] for r in output}=={r['id'] for r in records}
assert all(r['decision'] in ['Include','Exclude'] for r in output)
(p/'web_review_shahoud.json').write_text(json.dumps(output,indent=2,ensure_ascii=False))
from collections import Counter
print(Counter(r['decision'] for r in output)); print(Counter(r['evidence_level'] for r in output))
